//! Byte-for-byte compatibility with the TypeScript issuer and verifier.
//! `tests/vectors.json` is generated by `npm test` (packages/core-crypto/vectors.test.ts).

use primeid_core::{
    crypto::HolderKey,
    protocol::{build_answer, parse_scanned, to_canonical_json, Requester, Scanned},
    vault::VaultData,
};
use serde_json::Value;

#[test]
fn rust_device_reproduces_typescript_vectors() {
    let v: Value = serde_json::from_str(include_str!("vectors.json")).unwrap();
    let now = v["now"].as_u64().unwrap();
    let seed: [u8; 32] = hex::decode(v["app_seed"].as_str().unwrap()).unwrap().try_into().unwrap();
    let holder = HolderKey::from_app_seed(&seed);
    assert_eq!(holder.public_hex(), v["holder_pub"].as_str().unwrap(), "holder key derivation differs");

    let Scanned::Offer(offer) = parse_scanned(v["offer"].to_string().as_bytes()).unwrap() else { panic!("offer") };
    offer.verify_for_holder(&holder.public_hex(), now).unwrap();

    let Scanned::Request(req) = parse_scanned(v["request"].to_string().as_bytes()).unwrap() else { panic!("request") };
    req.verify_signature_and_time(now).unwrap();
    let mut vault = VaultData::default();
    vault.trust_issuer(&offer.cred.iss, &offer.cred.iss_name, now);
    assert!(matches!(req.requester(&vault.trusted_issuer_keys(), now), Requester::Verified { .. }));

    let disc = offer.disc.iter().find(|d| d.k == req.claim).unwrap();
    let answer = build_answer(&holder, &offer.cred, disc, &req).unwrap();
    assert_eq!(to_canonical_json(&answer).unwrap(), v["answer_canonical"].as_str().unwrap());
}
